using System;using System.Numerics;using System.Collections.Generic;using System.Text.Json;using EDJP.Observatory.Solver;class Program{static void Main(){var cases=new List<object>();var kicks=new List<object>();var engineType=typeof(Tsp3DSolver).GetNestedType("Engine",System.Reflection.BindingFlags.NonPublic);for(int seed=0;seed<8;seed++){var rng=new Random(seed);int n=14+seed*3;var points=new Vector3[n];for(int i=0;i<n;i++)points[i]=new Vector3(rng.Next(-20000,20000),rng.Next(-20000,20000),rng.Next(-20000,20000));var result=Tsp3DSolver.Solve(points,0,options:new Tsp3DSolver.Options{FreeEnd=true,TimeLimit=TimeSpan.FromSeconds(2),RandomSeed=seed,ParallelRestarts=false});var engine=Activator.CreateInstance(engineType,new object[]{points,0,null,false,true,new Tsp3DSolver.Options{FreeEnd=true},System.Threading.CancellationToken.None});var tour=System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Range(0,n+1));var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var greedy=(int[])engineType.GetMethod("GreedyConstruction",flags).Invoke(engine,null);var optimized=(int[])greedy.Clone();var greedyPos=new int[n+1];for(int k=0;k<n+1;k++)greedyPos[optimized[k]]=k;engineType.GetMethod("TwoOptOrOptPass",flags).Invoke(engine,new object[]{optimized,greedyPos});var bound=(double)engineType.GetMethod("ComputeLowerBound",flags).Invoke(engine,null);var pos=(int[])tour.Clone();engineType.GetMethod("DoubleBridge",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(engine,new object[]{tour,pos,new Random(seed)});var initialLength=(double)engineType.GetMethod("TourLength",flags).Invoke(engine,new object[]{optimized});var best=(int[])optimized.Clone();var bestLength=initialLength;var trace=new List<object>();var traceRng=new Random(seed);for(int iteration=0;iteration<16;iteration++){var candidate=(int[])best.Clone();var candidatePos=new int[n+1];for(int k=0;k<n+1;k++)candidatePos[candidate[k]]=k;engineType.GetMethod("DoubleBridge",flags).Invoke(engine,new object[]{candidate,candidatePos,traceRng});Tsp3DSolver.Trace.Clear();engineType.GetMethod("TwoOptOrOptPass",flags).Invoke(engine,new object[]{candidate,candidatePos});var length=(double)engineType.GetMethod("TourLength",flags).Invoke(engine,new object[]{candidate});if(length<bestLength-1e-9){best=(int[])candidate.Clone();bestLength=length;}trace.Add(new{candidate,length,best=(int[])best.Clone(),bestLength,ops=Tsp3DSolver.Trace.ToArray()});}kicks.Add(new{seed,n=n+1,tour,greedy,optimized,bound,initialLength,trace,neighbors=(int[][])engineType.GetField("Neighbors",flags).GetValue(engine)});cases.Add(new{seed,points=Array.ConvertAll(points,p=>new[]{p.X,p.Y,p.Z}),order=result.Order,length=result.Length,gap=result.EstimatedGapPercent,hitTimeLimit=result.HitTimeLimit});}var rng2=new Random(1234);var random=new List<int>();for(int i=1;i<=32;i++)random.Add(rng2.Next(i*1000));var randomSeeds=new List<object>();foreach(var seed in new[]{int.MinValue,-2000000000,-1,0,161803398,int.MaxValue}){var rng3=new Random(seed);var values=new List<int>();for(int i=1;i<=32;i++)values.Add(rng3.Next(i*1000));randomSeeds.Add(new{seed,values});}Console.Write(JsonSerializer.Serialize(new{cases,kicks,random,randomSeeds}));}}